<?php require 'includes/init.php'; $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $n=trim($_POST['name']??'');$em=trim($_POST['email']??'');$ph=trim($_POST['phone']??'');$pw=$_POST['password']??'';$cp=$_POST['confirm_password']??''; if($n===''||!filter_var($em,FILTER_VALIDATE_EMAIL)||!preg_match('/^[0-9+]{10,15}$/',$ph)||strlen($pw)<6)$err='Fill every field. Phone must be 10-15 digits and password at least 6 characters.'; elseif($pw!==$cp)$err='Passwords do not match.'; else try{Passenger::register($n,$em,$ph,$pw);header('Location: login.php?registered=1');exit;}catch(PDOException $e){$err=$e->getCode()==23000?'That email or phone number is already registered.':'Something went wrong.';}} include 'includes/header.php'; ?>
<main class="page"><div class="auth"><form class="card" method="post"><h1>Create Your Account</h1><p class="subtitle">Join EasyTrip and book your trips easily.</p><?php if($err): ?><div class="err"><?= e($err) ?></div><?php endif; ?><div class="field"><label>Full Name</label><input name="name" value="<?= e($_POST['name']??'') ?>" required></div><div class="field"><label>Email Address</label><input type="email" name="email" value="<?= e($_POST['email']??'') ?>" required></div><div class="field"><label>Phone Number</label><input name="phone" value="<?= e($_POST['phone']??'') ?>" required></div><div class="field"><label>Password</label><input type="password" name="password" required></div><div class="field"><label>Confirm Password</label><input type="password" name="confirm_password" required></div><button class="btn primary full">Sign Up</button><p class="helper">Already have an account? <a href="login.php">Login</a></p></form></div></main><?php include 'includes/footer.php'; ?>
